import * as stylex from '@stylexjs/stylex';
const SIZE = '100px';
const name = stylex.positionTry({
  top: '0',
  left: '0',
  width: SIZE,
  height: SIZE
});
export const styles = stylex.create({
  root: {
    positionTryFallbacks: name,
  }
});

import * as stylex from '@stylexjs/stylex';
